def listCollaborativeReasoningSessions(credential, status=None, stage=None, topicContains=None, updatedAfter=None, updatedBefore=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0305000" if __import__("os").path.isdir("./environment_mix/0305000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    allowed_status = {"active", "completed", "archived"}
    allowed_stage = {"problem-definition", "ideation", "critique", "integration", "decision", "reflection"}

    # ---- request logging + rate limit ----
    def _log(status_s, latency_ms):
        logf = "cr_request_log.json"
        logs = _load(logf)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "listCollaborativeReasoningSessions",
            "credential": credential,
            "status": status_s,
            "latency_ms": int(latency_ms),
            "timestamp": now,
        })
        _save(logf, logs)

    def _check_rate_limit():
        logf = "cr_request_log.json"
        logs = _load(logf)
        if not isinstance(logs, list):
            logs = []
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        # per-credential limit 60/min
        cnt = 0
        for r in logs[-5000:]:
            if r.get("credential") != credential:
                continue
            ts = r.get("timestamp")
            if isinstance(ts, str):
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    cnt += 1
        if cnt >= 60:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit_per_minute=60)
        return None

    # ---- authenticate credential (must exist somewhere, else UNAUTHORIZED) ----
    def _credential_exists():
        # Search any known credential store file(s) if present.
        # If none exist, accept any non-empty credential to avoid permanent refusal in minimal deployments.
        if not isinstance(credential, str) or credential.strip() == "":
            return False
        candidates = [
            "credentials.json", "api_keys.json", "access_tokens.json", "auth_tokens.json", "users.json"
        ]
        found_any_file = False
        for fn in candidates:
            path = os.path.join(_DB, fn)
            if os.path.exists(path):
                found_any_file = True
                rows = _load(fn)
                if isinstance(rows, list):
                    for r in rows:
                        if not isinstance(r, dict):
                            continue
                        for k in ("id", "token", "key", "value", "credential", "api_key", "access_token"):
                            if r.get(k) == credential:
                                return True
                elif isinstance(rows, dict):
                    # sometimes keyed by id
                    if credential in rows:
                        return True
        return True if not found_any_file else False

    rl = _check_rate_limit()
    if rl:
        _log("RATE_LIMIT", (time.time() - t0) * 1000.0)
        return rl
    if not _credential_exists():
        _log("UNAUTHORIZED", (time.time() - t0) * 1000.0)
        return _err("UNAUTHORIZED", "Invalid credential")

    # ---- validate filters ----
    if status is not None and status not in allowed_status:
        _log("VALIDATION_ERROR", (time.time() - t0) * 1000.0)
        return _err("VALIDATION_ERROR", "status must be one of the allowed enums", allowed=list(sorted(allowed_status)))
    if stage is not None and stage not in allowed_stage:
        _log("VALIDATION_ERROR", (time.time() - t0) * 1000.0)
        return _err("VALIDATION_ERROR", "stage must be one of the allowed enums", allowed=list(sorted(allowed_stage)))
    if topicContains is not None and not isinstance(topicContains, str):
        _log("VALIDATION_ERROR", (time.time() - t0) * 1000.0)
        return _err("VALIDATION_ERROR", "topicContains must be a string when provided")

    def _parse_dt(s, name):
        if s is None:
            return None
        if not isinstance(s, str) or s.strip() == "":
            return "BAD"
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return "BAD"

    ua = _parse_dt(updatedAfter, "updatedAfter")
    if ua == "BAD":
        _log("VALIDATION_ERROR", (time.time() - t0) * 1000.0)
        return _err("VALIDATION_ERROR", "updatedAfter must be RFC3339 date-time")
    ub = _parse_dt(updatedBefore, "updatedBefore")
    if ub == "BAD":
        _log("VALIDATION_ERROR", (time.time() - t0) * 1000.0)
        return _err("VALIDATION_ERROR", "updatedBefore must be RFC3339 date-time")

    if limit is None:
        limit_n = 50
    else:
        if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1 or limit > 200:
            _log("VALIDATION_ERROR", (time.time() - t0) * 1000.0)
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
        limit_n = limit

    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor.strip() == "":
            _log("VALIDATION_ERROR", (time.time() - t0) * 1000.0)
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or "offset" not in obj:
                raise ValueError("bad cursor")
            start = int(obj["offset"])
            if start < 0:
                raise ValueError("bad offset")
        except Exception:
            _log("VALIDATION_ERROR", (time.time() - t0) * 1000.0)
            return _err("VALIDATION_ERROR", "Invalid cursor")

    sessions = _load("cr_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    def _dt_updated(s):
        ts = s.get("updated_at")
        if isinstance(ts, str):
            try:
                return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).astimezone(datetime.timezone.utc).replace(tzinfo=None)
            except Exception:
                return datetime.datetime.min
        return datetime.datetime.min

    # Filter
    filtered = []
    tc = topicContains.lower() if isinstance(topicContains, str) else None
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if status is not None and s.get("status") != status:
            continue
        if stage is not None and s.get("stage") != stage:
            continue
        if tc is not None:
            top = s.get("topic")
            if not isinstance(top, str) or tc not in top.lower():
                continue
        udt = _dt_updated(s)
        if ua is not None and udt <= ua:
            continue
        if ub is not None and udt >= ub:
            continue
        filtered.append(s)

    # Sort updated_at desc
    filtered.sort(key=_dt_updated, reverse=True)

    total = len(filtered)
    page = filtered[start:start + limit_n]
    next_offset = start + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(json.dumps({"offset": next_offset}).encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit_n,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
        }
    }
    _log("OK", (time.time() - t0) * 1000.0)
    return resp

def getCollaborativeReasoningSession(credential, sessionId, include=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0305000" if __import__("os").path.isdir("./environment_mix/0305000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    allowed_inc = {"personas", "contributions", "disagreements"}

    def _log(status_s, latency_ms):
        logf = "cr_request_log.json"
        logs = _load(logf)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "getCollaborativeReasoningSession",
            "credential": credential,
            "status": status_s,
            "latency_ms": int(latency_ms),
            "timestamp": now,
        })
        _save(logf, logs)

    def _check_rate_limit():
        logf = "cr_request_log.json"
        logs = _load(logf)
        if not isinstance(logs, list):
            logs = []
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-5000:]:
            if r.get("credential") != credential:
                continue
            ts = r.get("timestamp")
            if isinstance(ts, str):
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if dt >= cutoff:
                    cnt += 1
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit_per_minute=120)
        return None

    def _credential_exists():
        if not isinstance(credential, str) or credential.strip() == "":
            return False
        candidates = ["credentials.json", "api_keys.json", "access_tokens.json", "auth_tokens.json", "users.json"]
        found_any_file = False
        for fn in candidates:
            if os.path.exists(os.path.join(_DB, fn)):
                found_any_file = True
                rows = _load(fn)
                if isinstance(rows, list):
                    for r in rows:
                        if not isinstance(r, dict):
                            continue
                        for k in ("id", "token", "key", "value", "credential", "api_key", "access_token"):
                            if r.get(k) == credential:
                                return True
                elif isinstance(rows, dict):
                    if credential in rows:
                        return True
        return True if not found_any_file else False

    rl = _check_rate_limit()
    if rl:
        _log("RATE_LIMIT", (time.time() - t0) * 1000.0)
        return rl
    if not _credential_exists():
        _log("UNAUTHORIZED", (time.time() - t0) * 1000.0)
        return _err("UNAUTHORIZED", "Invalid credential")

    if not isinstance(sessionId, str) or sessionId.strip() == "":
        _log("VALIDATION_ERROR", (time.time() - t0) * 1000.0)
        return _err("VALIDATION_ERROR", "sessionId must be a non-empty string")

    if include is None:
        include_set = set()
    else:
        if not isinstance(include, list) or any(not isinstance(i, str) for i in include):
            _log("VALIDATION_ERROR", (time.time() - t0) * 1000.0)
            return _err("VALIDATION_ERROR", "include must be an array of strings when provided")
        include_set = set(include)
        bad = [i for i in include if i not in allowed_inc]
        if bad:
            _log("VALIDATION_ERROR", (time.time() - t0) * 1000.0)
            return _err("VALIDATION_ERROR", "include contains invalid values", invalid=bad)

    sessions = _load("cr_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    sess = None
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == sessionId:
            sess = s
            break

    if sess is None:
        _log("NOT_FOUND", (time.time() - t0) * 1000.0)
        return _err("NOT_FOUND", "Session not found", sessionId=sessionId)

    resp = {"session": sess}

    if "personas" in include_set:
        personas_rows = _load("cr_personas.json")
        if not isinstance(personas_rows, list):
            personas_rows = []
        resp["personas"] = [p for p in personas_rows if isinstance(p, dict) and p.get("session_id") == sessionId]

    if "contributions" in include_set:
        contrib_rows = _load("cr_contributions.json")
        if not isinstance(contrib_rows, list):
            contrib_rows = []
        # deterministic ordering by sequence asc
        cs = [c for c in contrib_rows if isinstance(c, dict) and c.get("session_id") == sessionId]
        cs.sort(key=lambda r: r.get("sequence") if isinstance(r.get("sequence"), int) else 10**18)
        resp["contributions"] = cs

        # include references inline with contributions? tool doesn't ask; keep separate only if requested (not supported)
    if "disagreements" in include_set:
        disag_rows = _load("cr_disagreements.json")
        if not isinstance(disag_rows, list):
            disag_rows = []
        resp["disagreements"] = [d for d in disag_rows if isinstance(d, dict) and d.get("session_id") == sessionId]

    _log("OK", (time.time() - t0) * 1000.0)
    return resp

def updateCollaborativeReasoningSession(credential, sessionId, topic=None, stage=None, activePersonaId=None, nextPersonaId=None, iteration=None, nextContributionNeeded=None, suggestedContributionTypes=None, keyInsights=None, consensusPoints=None, openQuestions=None, finalRecommendation=None, status=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0305000" if __import__("os").path.isdir("./environment_mix/0305000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    allowed_status = {"active", "completed", "archived"}
    allowed_stage = {"problem-definition", "ideation", "critique", "integration", "decision", "reflection"}
    allowed_ctypes = {"observation", "question", "insight", "concern", "suggestion", "challenge", "synthesis"}
    transitions = {
        "active": {"completed", "archived"},
        "completed": {"archived"},
        "archived": set(),
    }

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _parse_ts(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    def _log(status_code, meta=None):
        logs = _ensure_list(_load("cr_request_logs.json"))
        logs.append({
            "id": "crl_" + uuid.uuid4().hex,
            "endpoint": "updateCollaborativeReasoningSession",
            "credential": credential,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "meta": meta or {},
        })
        _save("cr_request_logs.json", logs)

    def _check_rate_limit():
        logs = _ensure_list(_load("cr_request_logs.json"))
        cutoff = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-5000:]:
            if r.get("endpoint") != "updateCollaborativeReasoningSession":
                continue
            if r.get("credential") != credential:
                continue
            ts = _parse_ts(r.get("timestamp"))
            if ts is not None and ts >= cutoff:
                cnt += 1
        if cnt >= 60:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit_per_minute=60)
        return None

    # validate
    if not isinstance(credential, str) or not credential.strip():
        _log("VALIDATION_ERROR", meta={"field": "credential"})
        return _err("VALIDATION_ERROR", "credential must be a non-empty string", field="credential")
    if not isinstance(sessionId, str) or not sessionId.strip():
        _log("VALIDATION_ERROR", meta={"field": "sessionId"})
        return _err("VALIDATION_ERROR", "sessionId must be a non-empty string", field="sessionId")
    if stage is not None and stage not in allowed_stage:
        _log("VALIDATION_ERROR", meta={"field": "stage"})
        return _err("VALIDATION_ERROR", "Invalid stage", field="stage", allowed=sorted(allowed_stage))
    if status is not None and status not in allowed_status:
        _log("VALIDATION_ERROR", meta={"field": "status"})
        return _err("VALIDATION_ERROR", "Invalid status", field="status", allowed=sorted(allowed_status))
    if iteration is not None and (not isinstance(iteration, int) or iteration < 0):
        _log("VALIDATION_ERROR", meta={"field": "iteration"})
        return _err("VALIDATION_ERROR", "iteration must be an integer >= 0", field="iteration")
    if nextContributionNeeded is not None and not isinstance(nextContributionNeeded, bool):
        _log("VALIDATION_ERROR", meta={"field": "nextContributionNeeded"})
        return _err("VALIDATION_ERROR", "nextContributionNeeded must be a boolean", field="nextContributionNeeded")
    if suggestedContributionTypes is not None:
        if not isinstance(suggestedContributionTypes, list):
            _log("VALIDATION_ERROR", meta={"field": "suggestedContributionTypes"})
            return _err("VALIDATION_ERROR", "suggestedContributionTypes must be an array", field="suggestedContributionTypes")
        bad = [x for x in suggestedContributionTypes if x not in allowed_ctypes]
        if bad:
            _log("VALIDATION_ERROR", meta={"field": "suggestedContributionTypes"})
            return _err("VALIDATION_ERROR", "Invalid suggestedContributionTypes element(s)", field="suggestedContributionTypes", invalid=bad, allowed=sorted(allowed_ctypes))
    for fld, val in [("keyInsights", keyInsights), ("consensusPoints", consensusPoints), ("openQuestions", openQuestions)]:
        if val is not None and not isinstance(val, list):
            _log("VALIDATION_ERROR", meta={"field": fld})
            return _err("VALIDATION_ERROR", f"{fld} must be an array", field=fld)
    if finalRecommendation is not None and (not isinstance(finalRecommendation, str) or not finalRecommendation.strip()):
        _log("VALIDATION_ERROR", meta={"field": "finalRecommendation"})
        return _err("VALIDATION_ERROR", "finalRecommendation must be a non-empty string when provided", field="finalRecommendation")
    if topic is not None and (not isinstance(topic, str) or not topic.strip()):
        _log("VALIDATION_ERROR", meta={"field": "topic"})
        return _err("VALIDATION_ERROR", "topic must be a non-empty string when provided", field="topic")
    if activePersonaId is not None and (not isinstance(activePersonaId, str) or not activePersonaId.strip()):
        _log("VALIDATION_ERROR", meta={"field": "activePersonaId"})
        return _err("VALIDATION_ERROR", "activePersonaId must be a non-empty string when provided", field="activePersonaId")
    if nextPersonaId is not None and (not isinstance(nextPersonaId, str) or not nextPersonaId.strip()):
        _log("VALIDATION_ERROR", meta={"field": "nextPersonaId"})
        return _err("VALIDATION_ERROR", "nextPersonaId must be a non-empty string when provided", field="nextPersonaId")

    rl = _check_rate_limit()
    if rl:
        _log("RATE_LIMIT")
        return rl

    sessions = _ensure_list(_load("cr_sessions.json"))
    personas_rows = _ensure_list(_load("cr_personas.json"))

    sess = None
    idx = None
    for i, r in enumerate(sessions):
        if isinstance(r, dict) and r.get("id") == sessionId:
            sess = r
            idx = i
            break
    if sess is None:
        _log("NOT_FOUND", meta={"sessionId": sessionId})
        return _err("NOT_FOUND", "Session not found", sessionId=sessionId)

    # archived immutability
    if sess.get("status") == "archived":
        # allow only updated_at no-ops? vendor: immutable except updated_at/internal metadata migrations.
        # Since this tool updates mutable fields, refuse if any mutation requested other than none.
        requested = any(v is not None for v in [topic, stage, activePersonaId, nextPersonaId, iteration, nextContributionNeeded, suggestedContributionTypes, keyInsights, consensusPoints, openQuestions, finalRecommendation, status])
        if requested:
            _log("INVALID_TRANSITION", meta={"rule": "archived sessions immutable"})
            return _err("INVALID_TRANSITION", "Session is archived and cannot be modified", sessionId=sessionId)
        sess["updated_at"] = now
        sessions[idx] = sess
        _save("cr_sessions.json", sessions)
        _log("OK", meta={"archived_noop": True})
        return {"session": sess}

    # monotonic iteration
    if iteration is not None:
        prev_it = sess.get("iteration", 0)
        if not isinstance(prev_it, (int, float)):
            prev_it = 0
        if iteration < prev_it:
            _log("INVALID_TRANSITION", meta={"field": "iteration"})
            return _err("INVALID_TRANSITION", "iteration must be >= existing iteration", field="iteration", existing=prev_it, provided=iteration)

    # persona FK checks (must exist in same session, active)
    def _persona_ok(pid):
        for r in personas_rows:
            if isinstance(r, dict) and r.get("id") == pid and r.get("session_id") == sessionId:
                return r.get("status") == "active"
        return None  # not found

    if activePersonaId is not None:
        ok = _persona_ok(activePersonaId)
        if ok is None:
            _log("NOT_FOUND", meta={"field": "activePersonaId"})
            return _err("NOT_FOUND", "activePersonaId does not exist for this session", field="activePersonaId", id=activePersonaId, sessionId=sessionId)
        if ok is False:
            _log("VALIDATION_ERROR", meta={"field": "activePersonaId"})
            return _err("VALIDATION_ERROR", "activePersonaId must reference an active persona", field="activePersonaId", id=activePersonaId)

    if nextPersonaId is not None:
        ok = _persona_ok(nextPersonaId)
        if ok is None:
            _log("NOT_FOUND", meta={"field": "nextPersonaId"})
            return _err("NOT_FOUND", "nextPersonaId does not exist for this session", field="nextPersonaId", id=nextPersonaId, sessionId=sessionId)
        if ok is False:
            _log("VALIDATION_ERROR", meta={"field": "nextPersonaId"})
            return _err("VALIDATION_ERROR", "nextPersonaId must reference an active persona", field="nextPersonaId", id=nextPersonaId)

    # status transition checks
    cur_status = sess.get("status", "active")
    if status is not None and status != cur_status:
        if status not in transitions.get(cur_status, set()):
            _log("INVALID_TRANSITION", meta={"from": cur_status, "to": status})
            return _err("INVALID_TRANSITION", "Illegal status transition", from_status=cur_status, to_status=status)

        # business rule: when transitioning to completed, next_contribution_needed must be false and final_recommendation non-null
        if status == "completed":
            ncn = nextContributionNeeded if nextContributionNeeded is not None else sess.get("next_contribution_needed")
            fr = finalRecommendation if finalRecommendation is not None else sess.get("final_recommendation")
            if ncn is not False:
                _log("INVALID_TRANSITION", meta={"rule": "completion requires nextContributionNeeded=false"})
                return _err("INVALID_TRANSITION", "Cannot complete session while nextContributionNeeded is true", field="nextContributionNeeded")
            if fr is None or (isinstance(fr, str) and not fr.strip()):
                _log("INVALID_TRANSITION", meta={"rule": "completion requires finalRecommendation"})
                return _err("INVALID_TRANSITION", "Cannot complete session without finalRecommendation", field="finalRecommendation")

    # finalRecommendation constraint always
    effective_status = status if status is not None else cur_status
    effective_fr = finalRecommendation if finalRecommendation is not None else sess.get("final_recommendation")
    if effective_fr is not None and effective_status not in ("completed", "archived"):
        _log("VALIDATION_ERROR", meta={"field": "finalRecommendation"})
        return _err("VALIDATION_ERROR", "finalRecommendation requires session status to be completed or archived", field="finalRecommendation", status=effective_status)

    # apply updates; require at least one effective change, else NOT_FOUND-like? For update, return unchanged is allowed if session exists.
    changed = False
    def _set(k, v):
        nonlocal changed
        if v is not None and sess.get(k) != v:
            sess[k] = v
            changed = True

    _set("topic", topic)
    _set("stage", stage)
    if activePersonaId is not None:
        _set("active_persona_id", activePersonaId)
    if nextPersonaId is not None:
        _set("next_persona_id", nextPersonaId)
    if iteration is not None:
        _set("iteration", iteration)
    if nextContributionNeeded is not None:
        _set("next_contribution_needed", nextContributionNeeded)
    if suggestedContributionTypes is not None:
        _set("suggested_contribution_types", suggestedContributionTypes)
    if keyInsights is not None:
        _set("key_insights", keyInsights)
    if consensusPoints is not None:
        _set("consensus_points", consensusPoints)
    if openQuestions is not None:
        _set("open_questions", openQuestions)
    if finalRecommendation is not None:
        _set("final_recommendation", finalRecommendation)
    if status is not None:
        _set("status", status)

    # Always refresh updated_at if any field supplied (even same value) to reflect update call semantics
    if any(v is not None for v in [topic, stage, activePersonaId, nextPersonaId, iteration, nextContributionNeeded, suggestedContributionTypes, keyInsights, consensusPoints, openQuestions, finalRecommendation, status]):
        sess["updated_at"] = now
        changed = True

    sessions[idx] = sess

    try:
        _save("cr_sessions.json", sessions)
    except Exception as e:
        _log("CONFLICT", meta={"write_error": str(e)})
        return _err("CONFLICT", "Failed to persist session update", detail=str(e))

    _log("OK", meta={"changed": changed})
    return {"session": sess}

def listCollaborativeReasoningPersonas(credential, sessionId, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0305000" if __import__("os").path.isdir("./environment_mix/0305000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_list(v):
        return v if isinstance(v, list) else []

    def _audit(endpoint, cred_value, status_code, http_status, meta=None):
        logs = _ensure_list(_load("cr_request_logs.json"))
        rec = {
            "id": "crl_" + hashlib.sha256(f"{endpoint}|{cred_value}|{now}|{len(logs)}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "credential": cred_value,
            "status": status_code,
            "http_status": http_status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "meta": meta or {},
        }
        logs.append(rec)
        _save("cr_request_logs.json", logs)
        return rec

    def _parse_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur:
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"=" * (-len(cur) % 4)).decode("utf-8")
            if not raw.startswith("offset:"):
                return None
            off = int(raw.split(":", 1)[1])
            if off < 0:
                return None
            return off
        except Exception:
            return None

    def _make_cursor(off):
        s = f"offset:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(s).decode("utf-8").rstrip("=")

    # Validate inputs
    if not isinstance(credential, str) or not credential.strip():
        _audit("listCollaborativeReasoningPersonas", str(credential), "VALIDATION_ERROR", 400, {"field": "credential"})
        return _err("VALIDATION_ERROR", "credential must be a non-empty string", field="credential")
    if not isinstance(sessionId, str) or not sessionId.strip():
        _audit("listCollaborativeReasoningPersonas", credential, "VALIDATION_ERROR", 400, {"field": "sessionId"})
        return _err("VALIDATION_ERROR", "sessionId must be a non-empty string", field="sessionId")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "removed"):
            _audit("listCollaborativeReasoningPersonas", credential, "VALIDATION_ERROR", 400, {"field": "status"})
            return _err("VALIDATION_ERROR", "status must be one of: active, removed", field="status")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1 or limit > 200:
        _audit("listCollaborativeReasoningPersonas", credential, "VALIDATION_ERROR", 400, {"field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit")

    offset = _parse_cursor(cursor)
    if offset is None:
        _audit("listCollaborativeReasoningPersonas", credential, "VALIDATION_ERROR", 400, {"field": "cursor"})
        return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

    # Authenticate credential (ambient store may not exist; must refuse invalid/expired when explicit credential is required)
    auth = _ensure_list(_load("cr_credentials.json"))
    cred_row = None
    for r in auth:
        if isinstance(r, dict) and (r.get("id") == credential or r.get("value") == credential or r.get("token") == credential):
            if r.get("status") in (None, "active") and not r.get("revoked", False):
                cred_row = r
                break
    if cred_row is None and len(auth) > 0:
        _audit("listCollaborativeReasoningPersonas", credential, "UNAUTHORIZED", 401)
        return _err("UNAUTHORIZED", "Invalid or expired credential")

    sessions = _ensure_list(_load("cr_sessions.json"))
    sess = None
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == sessionId:
            sess = s
            break
    if sess is None:
        _audit("listCollaborativeReasoningPersonas", credential, "NOT_FOUND", 404, {"sessionId": sessionId})
        return _err("NOT_FOUND", "Session not found", sessionId=sessionId)

    personas = _ensure_list(_load("cr_personas.json"))
    rows = [p for p in personas if isinstance(p, dict) and p.get("session_id") == sessionId]
    if status is not None:
        rows = [p for p in rows if p.get("status") == status]

    # Deterministic ordering: created_at then id
    def _key(p):
        return (p.get("created_at") or "", p.get("id") or "")
    rows.sort(key=_key)

    total = len(rows)
    page = rows[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _make_cursor(next_off) if has_more else None

    _audit("listCollaborativeReasoningPersonas", credential, "OK", 200, {"sessionId": sessionId, "returned": len(page), "total": total})
    return {
        "object": "list",
        "data": page,
        "sessionId": sessionId,
        "total": total,
        "limit": limit,
        "cursor": cursor,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }

def updateCollaborativeReasoningPersona(credential, personaId, name=None, expertise=None, background=None, perspective=None, biases=None, communicationStyle=None, communicationTone=None, status=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0305000" if __import__("os").path.isdir("./environment_mix/0305000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    allowed_status = {"active", "removed"}
    transitions = {"active": {"removed"}, "removed": set()}

    def _ensure_list(x):
        return x if isinstance(x, list) else []

    def _parse_ts(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    def _log(status_code, meta=None):
        logs = _ensure_list(_load("cr_request_logs.json"))
        logs.append({
            "id": "crl_" + uuid.uuid4().hex,
            "endpoint": "updateCollaborativeReasoningPersona",
            "credential": credential,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            "meta": meta or {},
        })
        _save("cr_request_logs.json", logs)

    def _check_rate_limit():
        logs = _ensure_list(_load("cr_request_logs.json"))
        cutoff = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-5000:]:
            if r.get("endpoint") != "updateCollaborativeReasoningPersona":
                continue
            if r.get("credential") != credential:
                continue
            ts = _parse_ts(r.get("timestamp"))
            if ts is not None and ts >= cutoff:
                cnt += 1
        if cnt >= 60:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit_per_minute=60)
        return None

    # ---- Validate credential (explicit parameter) ----
    if not isinstance(credential, str) or not credential.strip():
        e = _err("VALIDATION_ERROR", "credential must be a non-empty string.")
        _log(400, {"error": e["error"]})
        return e

    # Authenticate against any supported credential store, but never via hashes.
    # If no credential store exists, accept any non-empty credential (offline dev mode).
    cred_ok = False
    cred_meta = None
    creds = _load("cr_credentials.json")
    if isinstance(creds, list) and creds:
        for c in creds:
            if not isinstance(c, dict):
                continue
            if credential == c.get("id") or credential == c.get("token") or credential == c.get("value") or credential == c.get("api_key"):
                # if credential rows have status, require active
                if c.get("status") in (None, "active", "enabled"):
                    cred_ok = True
                    cred_meta = {"credential_id": c.get("id")}
                    break
    else:
        cred_ok = True  # dev fallback

    if not cred_ok:
        e = _err("UNAUTHORIZED", "Invalid credential.")
        _log(401, {"error": e["error"]})
        return e

    # ---- Rate limit ----
    rl = _check_rate_limit()
    if rl:
        _log(429, {"error": rl["error"], **(cred_meta or {})})
        return rl

    # ---- Validate inputs ----
    if not isinstance(personaId, str) or not personaId.strip():
        e = _err("VALIDATION_ERROR", "personaId must be a non-empty string.")
        _log(400, {"error": e["error"], **(cred_meta or {})})
        return e

    if status is not None and status not in allowed_status:
        e = _err("VALIDATION_ERROR", "status must be one of the allowed values.", allowed=sorted(allowed_status))
        _log(400, {"error": e["error"], **(cred_meta or {})})
        return e

    if name is not None and (not isinstance(name, str) or not name.strip()):
        e = _err("VALIDATION_ERROR", "name must be a non-empty string when provided.")
        _log(400, {"error": e["error"], **(cred_meta or {})})
        return e

    if expertise is not None:
        if not isinstance(expertise, list) or len(expertise) < 1 or any(not isinstance(x, str) for x in expertise):
            e = _err("VALIDATION_ERROR", "expertise must be an array of >=1 strings when provided.")
            _log(400, {"error": e["error"], **(cred_meta or {})})
            return e

    if background is not None and (not isinstance(background, str) or not background.strip()):
        e = _err("VALIDATION_ERROR", "background must be a non-empty string when provided.")
        _log(400, {"error": e["error"], **(cred_meta or {})})
        return e

    if perspective is not None and (not isinstance(perspective, str) or not perspective.strip()):
        e = _err("VALIDATION_ERROR", "perspective must be a non-empty string when provided.")
        _log(400, {"error": e["error"], **(cred_meta or {})})
        return e

    if biases is not None:
        if not isinstance(biases, list) or any(not isinstance(x, str) for x in biases):
            e = _err("VALIDATION_ERROR", "biases must be an array of strings when provided.")
            _log(400, {"error": e["error"], **(cred_meta or {})})
            return e

    if communicationStyle is not None and (not isinstance(communicationStyle, str) or not communicationStyle.strip()):
        e = _err("VALIDATION_ERROR", "communicationStyle must be a non-empty string when provided.")
        _log(400, {"error": e["error"], **(cred_meta or {})})
        return e

    if communicationTone is not None and (not isinstance(communicationTone, str) or not communicationTone.strip()):
        e = _err("VALIDATION_ERROR", "communicationTone must be a non-empty string when provided.")
        _log(400, {"error": e["error"], **(cred_meta or {})})
        return e

    # ---- Load and update persona ----
    personas_rows = _ensure_list(_load("cr_personas.json"))
    sessions = _ensure_list(_load("cr_sessions.json"))

    idx = None
    pr = None
    for i, row in enumerate(personas_rows):
        if row.get("id") == personaId:
            idx = i
            pr = row
            break

    if pr is None:
        e = _err("NOT_FOUND", "Persona not found.", personaId=personaId)
        _log(404, {"error": e["error"], **(cred_meta or {})})
        return e

    # If session archived, persona roster should be immutable
    sess_id = pr.get("session_id")
    sess = None
    for s in sessions:
        if s.get("id") == sess_id:
            sess = s
            break
    if sess is not None and sess.get("status") == "archived":
        e = _err("INVALID_TRANSITION", "Session is archived; persona is immutable.", sessionId=sess_id)
        _log(409, {"error": e["error"], **(cred_meta or {})})
        return e

    # Lifecycle transition
    if status is not None:
        cur = pr.get("status")
        if cur not in transitions:
            e = _err("INVALID_TRANSITION", "Persona has an unknown lifecycle status; cannot transition.", current_status=cur)
            _log(409, {"error": e["error"], **(cred_meta or {})})
            return e
        if status != cur:
            if status not in transitions[cur]:
                e = _err("INVALID_TRANSITION", "Illegal persona status transition.", from_status=cur, to_status=status, allowed=list(transitions[cur]))
                _log(409, {"error": e["error"], **(cred_meta or {})})
                return e
            pr["status"] = status

    # Refuse editing removed personas (immutable once removed)
    if pr.get("status") == "removed":
        # You may still have removed it above; if any other field updates are requested, refuse.
        if any(x is not None for x in (name, expertise, background, perspective, biases, communicationStyle, communicationTone)):
            e = _err("INVALID_TRANSITION", "Removed personas are immutable and cannot be edited.", personaId=personaId)
            _log(409, {"error": e["error"], **(cred_meta or {})})
            return e

    # Apply field updates for active personas
    changed = False
    if name is not None:
        pr["name"] = name
        changed = True
    if expertise is not None:
        pr["expertise"] = expertise
        changed = True
    if background is not None:
        pr["background"] = background
        changed = True
    if perspective is not None:
        pr["perspective"] = perspective
        changed = True
    if biases is not None:
        pr["biases"] = biases
        changed = True
    if communicationStyle is not None:
        pr["communication_style"] = communicationStyle
        changed = True
    if communicationTone is not None:
        pr["communication_tone"] = communicationTone
        changed = True

    # Enforce constraint: expertise length >= 1 (always)
    if not isinstance(pr.get("expertise"), list) or len(pr["expertise"]) < 1:
        e = _err("VALIDATION_ERROR", "expertise must contain at least one entry.")
        _log(400, {"error": e["error"], **(cred_meta or {})})
        return e

    # Must not report success with no effect for a mutation
    if not changed and status is None:
        e = _err("CONFLICT", "No changes requested.")
        _log(409, {"error": e["error"], **(cred_meta or {})})
        return e

    pr["updated_at"] = now
    personas_rows[idx] = pr
    _save("cr_personas.json", personas_rows)

    _log(200, {"personaId": personaId, "sessionId": sess_id, **(cred_meta or {})})
    return {"persona": pr}

def getCollaborativeReasoningIdentity(credential, **_extra):
