    for r in all_logs[-20000:]:
        if not isinstance(r, dict):
            continue
        if r.get("credential") != credential:
            continue
        ts = _parse_ts(r.get("timestamp"))
        if ts is not None and ts >= day_cutoff:
            used_24h += 1

    # choose a quota number if present on credential row, else default
    quota_limit = None
    if cred_row is not None:
        for k in ("quota_per_day", "daily_quota", "quota_daily", "quota_24h"):
            if isinstance(cred_row.get(k), int):
                quota_limit = cred_row.get(k)
                break
    if quota_limit is None:
        quota_limit = 5000

    if used_24h >= quota_limit:
        _audit("QUOTA_EXCEEDED", meta={"quota_per_24h": quota_limit, "used_24h": used_24h})
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded", quota_per_24h=quota_limit, used_24h=used_24h)

    identity = {
