        "scopes": cred_row.get("scopes") if isinstance((cred_row or {}).get("scopes"), list) else ["collaborative_reasoning:read", "collaborative_reasoning:write"],
    }
    if sess is not None:
        identity["session_fallback"] = {"session_id": sess.get("id"), "session_status": sess.get("status")}

    _audit("OK", meta={"used_24h": used_24h, "quota_per_24h": quota_limit})
    return {
        "identity": identity,
        "rate_limit": {"limit_per_minute": 120, "window_seconds": 60},
        "quota": {"quota_per_24h": quota_limit, "used_24h": used_24h, "remaining_24h": max(0, quota_limit - used_24h)},
    }
